"""Generate theme-aware SVG sequence diagrams and inject them into architecture.html.

Usage: python3 -I fork/scripts/render-diagrams.py fork/architecture.html
Replaces <!--SEQ:name--> placeholders (or a previously generated block) in place.
"""

# Standalone script, not a package; its SVG/CSS template lines are long on purpose.
# ruff: noqa: E501, INP001, PLR0915

import html
import re
import sys
from pathlib import Path


CHAR_W = 6.9  # IBM Plex Mono at 11.5px, average advance
MARGIN = 16
HEAD_H = 48
STEP = 34

CSS = """
/* sequence diagrams (generated by fork/scripts/render-diagrams.py) */
.seq { overflow-x: auto; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); padding: 10px; }
.seq svg { display: block; min-width: 760px; width: 100%; height: auto; }
.seq .hd { stroke: none; }
.seq .hd-dev { fill: var(--code-bg); }
.seq .hd-fork { fill: var(--fork-soft); }
.seq .hd-patch { fill: var(--patch-soft); }
.seq .hd-up { fill: var(--up-soft); }
.seq .hd-ok { fill: var(--ok-soft); }
.seq .pl { fill: var(--ink); font-family: var(--font-display); font-size: 13px; font-weight: 600; }
.seq .ps { fill: var(--muted); font-family: var(--font-mono); font-size: 10.5px; }
.seq .life { stroke: var(--line); stroke-width: 1.5; stroke-dasharray: 4 4; }
.seq .m { stroke: var(--ink); stroke-width: 1.4; fill: none; }
.seq .m-ret { stroke: var(--muted); stroke-width: 1.4; fill: none; stroke-dasharray: 5 4; }
.seq .m-ok { stroke: var(--ok); stroke-width: 1.6; fill: none; }
.seq .m-bad { stroke: var(--bad); stroke-width: 1.6; fill: none; }
.seq .ml { fill: var(--ink); font-family: var(--font-mono); font-size: 11.5px; }
.seq .ml-ret { fill: var(--muted); font-family: var(--font-mono); font-size: 11.5px; }
.seq .ml-ok { fill: var(--ok); font-family: var(--font-mono); font-size: 11.5px; font-weight: 500; }
.seq .ml-bad { fill: var(--bad); font-family: var(--font-mono); font-size: 11.5px; font-weight: 500; }
.seq .num { fill: var(--fork); font-family: var(--font-mono); font-size: 10.5px; font-weight: 500; }
.seq .a { fill: var(--ink); }
.seq .a-ret { fill: var(--muted); }
.seq .a-ok { fill: var(--ok); }
.seq .a-bad { fill: var(--bad); }
.seq .frame { fill: none; stroke: var(--muted); stroke-width: 1; }
.seq .frame-sep { stroke: var(--muted); stroke-width: 1; stroke-dasharray: 6 4; }
.seq .tab { fill: var(--bg); stroke: var(--muted); stroke-width: 1; }
.seq .tabt { fill: var(--ink); font-family: var(--font-mono); font-size: 10.5px; font-weight: 500; }
.seq .guard { fill: var(--muted); font-family: var(--font-mono); font-size: 10.5px; }
.seq .note { fill: var(--patch-soft); stroke: none; }
.seq .notet { fill: var(--ink); font-family: var(--font-body); font-size: 11.5px; }
"""

DIAGRAMS = {
    "develop": {
        "title": "Develop: edit the source, test, save patches, commit code and patches, CI verify",
        "cw": 150,
        "parts": [
            ("dev", "Developer", "you", "dev"),
            ("tree", "Repo source", "files you edit", "up"),
            ("cli", "fork/dev", "command runner", "fork"),
            ("pat", "fork/patches", "*.patch in git", "patch"),
            ("gh", "GitHub + CI", "PR review", "ok"),
        ],
        "steps": [
            ("note", "dev", "tree", "Edit any file in the source"),
            ("msg", "dev", "cli", "test"),
            ("msg", "cli", "tree", "lint + tests"),
            ("ret", "cli", "dev", "results"),
            ("msg", "dev", "cli", "save"),
            ("msg", "cli", "tree", "diff checkpoint"),
            ("msg", "cli", "pat", "write .patch"),
            ("msg", "dev", "gh", "commit code + patches, open PR"),
            ("note", "pat", "gh", "Reviewers read the code diff"),
            ("self", "gh", "fork/dev verify"),
            ("ok", "gh", "dev", "✓ patches match the code"),
        ],
    },
    "sync": {
        "title": "Sync: back to checkpoint, remove our changes, take latest upstream, re-apply patches",
        "cw": 140,
        "parts": [
            ("dev", "Maintainer", "you", "dev"),
            ("cli", "fork/dev sync", "sync-upstream.sh", "fork"),
            ("up", "Upstream", "usestrix/strix", "up"),
            ("br", "Sync branch", "sync/upstream-*", "fork"),
            ("tree", "Working tree", "files on disk", "patch"),
            ("gh", "GitHub + CI", "PR review", "ok"),
        ],
        "steps": [
            ("msg", "dev", "cli", "sync v1.7.2"),
            ("msg", "cli", "up", "fetch upstream"),
            ("ret", "up", "cli", "v1.7.2"),
            ("msg", "cli", "br", "branch from main"),
            ("msg", "cli", "tree", "back to checkpoint"),
            ("note", "cli", "tree", "All patched changes removed: pure upstream"),
            ("msg", "cli", "br", "take v1.7.2 (clean)"),
            ("msg", "cli", "tree", "re-apply patches (3-way)"),
            ("alt", "a patch fails"),
            ("bad", "tree", "dev", "✗ CONFLICT in <file>"),
            ("msg", "dev", "tree", "fix the code"),
            ("msg", "dev", "cli", "sync --continue"),
            ("end",),
            ("msg", "cli", "br", "move checkpoint, merge commit"),
            ("msg", "dev", "gh", "push + PR into main"),
            ("self", "gh", "fork/dev verify"),
            ("ok", "gh", "dev", "✓ merge commit (never squash)"),
        ],
    },
    "build": {
        "title": "Build and release: the code in git is already patched",
        "cw": 150,
        "parts": [
            ("dev", "Maintainer", "you", "dev"),
            ("ci", "CI runner", "fork-release.yml", "ok"),
            ("cli", "fork/dev", "command runner", "fork"),
            ("tools", "Build tools", "uv, PyInstaller", "up"),
            ("rel", "GitHub Releases", "our repo", "fork"),
        ],
        "steps": [
            ("msg", "dev", "ci", "push tag"),
            ("note", "ci", "tools", "Checkout with full history. Code is already patched."),
            ("msg", "ci", "cli", "build binary"),
            ("self", "cli", "verify"),
            ("msg", "cli", "tools", "scripts/build.sh"),
            ("ret", "tools", "ci", "wheel + binaries"),
            ("msg", "ci", "rel", "upload assets"),
            ("ok", "rel", "dev", "✓ v1.7.2-jitera.1 published"),
        ],
    },
}


def esc(t):
    return html.escape(t, quote=True)


def render(name, spec):
    cw = spec["cw"]
    parts = spec["parts"]
    x = {p[0]: MARGIN + cw / 2 + i * cw for i, p in enumerate(parts)}
    width = MARGIN * 2 + cw * len(parts)
    left, right = MARGIN + 4, width - MARGIN - 4
    out, warns = [], []
    y = MARGIN + HEAD_H + 22
    n = 0
    frames = []

    def arrow_id(kind):
        return f"{name}-{kind}"

    for step in spec["steps"]:
        kind = step[0]
        if kind in ("msg", "ret", "ok", "bad"):
            _, a, b, label = step
            n += 1
            y += STEP
            x1, x2 = x[a], x[b]
            d = 1 if x2 > x1 else -1
            cls = {"msg": "m", "ret": "m-ret", "ok": "m-ok", "bad": "m-bad"}[kind]
            tcls = {"msg": "ml", "ret": "ml-ret", "ok": "ml-ok", "bad": "ml-bad"}[kind]
            out.append(
                f'<line class="{cls}" x1="{x1 + 3 * d:.1f}" y1="{y}" x2="{x2 - 4 * d:.1f}" y2="{y}" marker-end="url(#{arrow_id(cls)})"/>'
            )
            text = f"{label}"
            span = abs(x2 - x1)
            tw = (len(text) + 3) * CHAR_W
            if tw > span - 8:
                warns.append(f"{name} step {n}: '{text}' {tw:.0f}px > span {span:.0f}px")
            cx = (x1 + x2) / 2
            out.append(f'<text class="num" x="{cx - tw / 2:.1f}" y="{y - 7}">{n}</text>')
            out.append(
                f'<text class="{tcls}" x="{cx - tw / 2 + 3 * CHAR_W:.1f}" y="{y - 7}">{esc(text)}</text>'
            )
        elif kind == "self":
            _, a, label = step
            n += 1
            y += STEP
            xa = x[a]
            out.append(
                f'<path class="m" d="M{xa + 3:.1f} {y - 8} h28 v16 h-26" marker-end="url(#{arrow_id("m")})"/>'
            )
            lw = (len(label) + 3) * CHAR_W
            # No room on the right edge: put the label left of the lifeline.
            lx = xa + 38 if xa + 38 + lw <= right else xa - 10 - lw
            out.append(f'<text class="num" x="{lx:.1f}" y="{y + 4}">{n}</text>')
            out.append(
                f'<text class="ml" x="{lx + 3 * CHAR_W:.1f}" y="{y + 4}">{esc(label)}</text>'
            )
            y += 10
        elif kind == "note":
            _, a, b, text = step
            y += STEP - 4
            xa, xb = sorted((x[a], x[b]))
            nx, nw = xa - 52, (xb - xa) + 104
            out.append(
                f'<rect class="note" x="{nx:.1f}" y="{y - 17}" width="{nw:.1f}" height="26" rx="5"/>'
            )
            out.append(
                f'<text class="notet" x="{(xa + xb) / 2:.1f}" y="{y}" text-anchor="middle">{esc(text)}</text>'
            )
            if len(text) * 6.3 > nw - 12:
                warns.append(f"{name} note too long: {text}")
        elif kind == "alt":
            y += 22
            frames.append({"top": y - 12, "seps": [], "label": step[1]})
            out.append(("__TAB__", len(frames) - 1))
            y += 6
        elif kind == "else":
            y += 20
            frames[-1]["seps"].append((y - 10, step[1]))
            y += 4
        elif kind == "end":
            y += 16
            f = frames[-1]
            f["bottom"] = y
            fi = len(frames) - 1
            body = [
                f'<rect class="frame" x="{left}" y="{f["top"]}" width="{right - left}" height="{f["bottom"] - f["top"]}" rx="4"/>'
            ]
            body.append(f'<path class="tab" d="M{left} {f["top"]} h40 v14 l-6 6 h-34 z"/>')
            body.append(f'<text class="tabt" x="{left + 8}" y="{f["top"] + 14}">alt</text>')
            body.append(
                f'<text class="guard" x="{left + 48}" y="{f["top"] + 14}">[{esc(f["label"])}]</text>'
            )
            for sy, lab in f["seps"]:
                body.append(
                    f'<line class="frame-sep" x1="{left}" y1="{sy}" x2="{right}" y2="{sy}"/>'
                )
                body.append(f'<text class="guard" x="{left + 8}" y="{sy + 14}">[{esc(lab)}]</text>')
            out = [("\n".join(body) if (isinstance(o, tuple) and o[1] == fi) else o) for o in out]
    height = y + 26

    svg = [
        f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{esc(spec["title"])}">'
    ]
    svg.append("<defs>")
    for cls, acls in (("m", "a"), ("m-ret", "a-ret"), ("m-ok", "a-ok"), ("m-bad", "a-bad")):
        svg.append(
            f'<marker id="{arrow_id(cls)}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path class="{acls}" d="M0,0 L10,5 L0,10 z"/></marker>'
        )
    svg.append("</defs>")
    for pid, label, sub, style in parts:
        cx = x[pid]
        bw = cw - 16
        svg.append(
            f'<rect class="hd hd-{style}" x="{cx - bw / 2:.1f}" y="{MARGIN}" width="{bw}" height="{HEAD_H}" rx="8"/>'
        )
        svg.append(
            f'<text class="pl" x="{cx:.1f}" y="{MARGIN + 21}" text-anchor="middle">{esc(label)}</text>'
        )
        svg.append(
            f'<text class="ps" x="{cx:.1f}" y="{MARGIN + 37}" text-anchor="middle">{esc(sub)}</text>'
        )
        svg.append(
            f'<line class="life" x1="{cx:.1f}" y1="{MARGIN + HEAD_H}" x2="{cx:.1f}" y2="{height - 8}"/>'
        )
    svg.extend(o for o in out if isinstance(o, str))
    svg.append("</svg>")
    block = (
        f'<div class="seq"><!--SEQGEN:{name}-->\n'
        + "\n".join(svg)
        + f"\n<!--/SEQGEN:{name}--></div>"
    )
    return block, warns


def main(path):
    s = Path(path).read_text()
    all_warns = []
    for name, spec in DIAGRAMS.items():
        block, warns = render(name, spec)
        all_warns += warns
        placeholder = f"<!--SEQ:{name}-->"
        pat = re.compile(
            r'<div class="seq"><!--SEQGEN:' + name + r"-->.*?<!--/SEQGEN:" + name + r"--></div>",
            re.S,
        )
        if placeholder in s:
            s = s.replace(placeholder, block)
        elif pat.search(s):
            s = pat.sub(lambda _m, b=block: b, s)
        else:
            raise SystemExit(f"no placeholder for {name}")
    if "/* sequence diagrams (generated by fork/scripts/render-diagrams.py) */" not in s:
        s = s.replace("</style>", CSS + "</style>", 1)
    Path(path).write_text(s)
    sys.stdout.write(("\n".join(all_warns) if all_warns else "no label overflow") + "\n")


main(sys.argv[1])
